-- 711: TÜRKİYE KLİNİK KALİTE PROGRAMI — sağlık olguları, göstergeler ve kod listeleri.
--
-- KAYNAK: T.C. Sağlık Bakanlığı, Sağlık Hizmetleri Genel Müdürlüğü, Sağlıkta
--   Kalite, Akreditasyon ve Çalışan Hakları Dairesi Başkanlığı —
--   "Klinik Kalite Ölçme ve Değerlendirme Rehberi (Sürüm 1.1)", Mart 2021.
--   16 sağlık olgusu · 217 gösterge · 929 tekil kod (ICD-10 / SUT / ATC).
--
-- BU, SKS GÖSTERGELERİ DEĞİLDİR. SKS (Gösterge Yönetimi Rehberi) kurumun nasıl
--   işlediğini ölçer ve verisi elle toplanır; Klinik Kalite hastanın doğru
--   tedavi edilip edilmediğini ölçer ve verisi HBYS'den (tanı + işlem + ilaç)
--   hesaplanır. İki program ayrı yürür, tabloları da ayrıdır.
--
-- TEMEL KARAR — KOD UYDURULMAZ. Gösterge kodu Bakanlığın kodudur (DP.G1,
--   DM.G12 ...). Kendi sıra numaramızı anahtar yapsaydık rehber bir gösterge
--   iptal edip yenisini eklediğinde numaralarımız kayar ve geçmiş dönem
--   ölçümleri yanlış göstergeye bağlanırdı.
--
-- TEMEL KARAR — STANDART TABLOSU BOŞ KURULUR. Standardın METNİ her gösterge
--   kartında var (ve `klinik_gosterge.standart_metin` olarak yüklendi) ama
--   resmî KODU (DP.S1) yalnız olgu giriş sayfalarında geçiyor; o sayfalar iki
--   sütun dizilmiş ve metin çıkarımı güvenilir sonuç vermiyor. Metinden
--   türetmek denendi: rehberin kendi saydığı standart sayısıyla tutmadı
--   (Diz Protezi'nde 4 yerine 5, DM'de 3 yerine 12 çıktı - aynı standart
--   kartlarda farklı sözcüklerle yazılmış). Yanlış S-numarası, göstergeyi
--   yanlış resmî standarda bağlar; boş bırakmak daha az zararlı. Tablo hazır,
--   kodlar elde edilince doldurulur.
--
-- TEMEL KARAR — HEDEF HEM METİN HEM SAYI. Rehber hedefi serbest metin yazıyor
--   ("≤ %0.8", "≥% 60", "≤ 3 gün"). Metin kaynağın kendisidir ve saklanır;
--   ayrıca yön + değer + birim olarak ayrıştırılır ki "hedefte mi" sorusu
--   SQL'de yanıtlanabilsin. Yalnız sayıyı saklasaydık rehberin ifadesi
--   kaybolur, yalnız metni saklasaydık her karşılaştırma ekranda yapılırdı.
--
-- TEMEL KARAR — KURUM HEDEFİ AYRI KOLON. Rehberin ulusal hedefi salt okunur;
--   kurum kendi (daha sıkı) hedefini ayrı alana yazar. Tek alan olsaydı kurum
--   hedefini girince ulusal hedef kaybolur, sapma neye göre ölçülüyor
--   belirsizleşirdi.
--
-- TEMEL KARAR — KOD LİSTESİ REHBERİN MALI. `klinik_gosterge_kod` kurum
--   tarafından düzenlenmez: kod kümesi değişirse üretilen sayı Bakanlığın
--   hesabıyla tutmaz ve gösterge kıyaslanamaz hale gelir. Rehber
--   güncellendiğinde liste toplu tazelenir (kaynak_surum ile).
--
-- TEMEL KARAR — SONUCU TEK YER HESAPLAR. pay/payda girilir, `sonuc` tetikte
--   `fn_klinik_gosterge_sonuc` ile yazılır; istemci ya da ikinci bir sunucu
--   yolu aynı oranı yeniden hesaplamaz.

-- ============================================================ sağlık olgusu ==
create table if not exists public.klinik_olgu (
  id            integer generated by default as identity primary key,
  -- Bakanlığın iki/üç harfli kısaltması: DP, DM, GD, KB ... (rehber II.1.1).
  kod           varchar(8)   not null,
  ad            varchar(120) not null,
  sira          smallint     not null default 0,
  aktif         smallint     not null default 1,
  ekleyen       integer      not null default 0,
  ekleme_tarihi timestamptz  not null default now()
);
create unique index if not exists ux_klinik_olgu_kod on public.klinik_olgu (kod);

comment on table public.klinik_olgu is
  'Klinik Kalite sağlık olgusu (711). Kod Bakanlığın kısaltmasıdır: DP, DM, GD…';

-- ================================================================ standart ==
-- BOŞ KURULUR - yukarıdaki "STANDART TABLOSU BOŞ KURULUR" kararına bakınız.
--   `kod` resmî S-kodudur (DP.S1) ve elde edilene kadar NULL kalır.
create table if not exists public.klinik_standart (
  id       integer generated by default as identity primary key,
  olgu_id  integer not null references public.klinik_olgu(id) on delete cascade,
  kod      varchar(16),
  sira     smallint not null default 0,
  metin    text     not null default ''
);
create index if not exists ix_klinik_standart_olgu on public.klinik_standart (olgu_id, sira);

-- ================================================================ gösterge ==
create table if not exists public.klinik_gosterge (
  id             integer generated by default as identity primary key,
  olgu_id        integer not null references public.klinik_olgu(id) on delete cascade,
  standart_id    integer references public.klinik_standart(id),
  kod            varchar(20)  not null,
  ad             varchar(400) not null,
  tanim          text not null default '',
  -- Standardın metni karttan gelir; resmî kodu bilinmediği için burada durur.
  standart_metin text not null default '',
  hesaplama      text not null default '',
  teknik_not     text not null default '',
  hedef_grup     text not null default '',
  haric          text not null default '',
  -- İzlem düzeyi: U ulusal · B bölgesel · K kurumsal (rehber II.2.1).
  izlem          varchar(3) not null default '',
  -- Rehberin hedefi: hem yazıldığı gibi hem ayrıştırılmış hali.
  hedef_metin    varchar(60) not null default '',
  hedef_yon      varchar(2),               -- >= · <= · > · <
  hedef_deger    numeric(10,4),
  hedef_birim    varchar(12) not null default '',   -- yuzde · gün · saat · dakika
  -- Kurumun kendi (daha sıkı olabilen) hedefi.
  kurum_hedef_yon   varchar(2),
  kurum_hedef_deger numeric(10,4),
  periyot_metin  varchar(60) not null default '',
  periyot        smallint not null default 0,       -- 3 · 6 · 12 ay
  -- Kod listesi var mı: yoksa gösterge HBYS'den hesaplanamaz, elle beslenir.
  --   Ekranda "Veri Eksik" sekmesini bu alan besler; boş satır bırakıp
  --   kullanıcıyı "neden hesaplanmadı" diye aratmamak için saklanır.
  otomatik       smallint not null default 0,
  rehber_surum   varchar(20) not null default 'S.1.1',
  aktif          smallint not null default 1,
  ekleyen        integer not null default 0,
  ekleme_tarihi  timestamptz not null default now(),
  degistiren     integer not null default 0,
  degistirme_tarihi timestamptz
);
create unique index if not exists ux_klinik_gosterge_kod on public.klinik_gosterge (kod);
create index if not exists ix_klinik_gosterge_olgu on public.klinik_gosterge (olgu_id, kod);

comment on table public.klinik_gosterge is
  'Klinik Kalite göstergesi (711). Kod Bakanlığın kodudur (DP.G1…); hedef hem metin hem ayrıştırılmış.';

-- ========================================================== kod listeleri ==
-- Göstergenin payını ve paydasını TANIMLAYAN kod kümesi. Rehberden gelir,
--   kurum düzenlemez. Bir gösterge aynı kodu hem pay hem payda tarafında
--   kullanabilir, bu yüzden benzersizlik role de bağlıdır.
create table if not exists public.klinik_gosterge_kod (
  id           bigint generated by default as identity primary key,
  gosterge_id  integer not null references public.klinik_gosterge(id) on delete cascade,
  rol          varchar(6) not null,          -- pay · payda
  tip          varchar(6) not null,          -- icd10 · sut · atc
  kod          varchar(20) not null,
  aciklama     varchar(200) not null default '',
  sira         smallint not null default 0,
  kaynak_surum varchar(20) not null default 'S.1.1'
);
create unique index if not exists ux_klinik_gkod_benzersiz
  on public.klinik_gosterge_kod (gosterge_id, rol, tip, kod);
-- Ters yön: "bu ICD kodu hangi göstergeleri besliyor" (Kod Havuzu ekranı).
create index if not exists ix_klinik_gosterge_kod_kod
  on public.klinik_gosterge_kod (tip, kod);

comment on table public.klinik_gosterge_kod is
  'Göstergenin pay/payda kod kümesi (711): ICD-10 tanı · SUT işlem · ATC ilaç. Rehberden gelir, düzenlenmez.';

-- ============================================================ dönem ölçümü ==
create table if not exists public.klinik_gosterge_donem (
  id            bigint generated by default as identity primary key,
  sube_id       integer not null default 0,
  gosterge_id   integer not null references public.klinik_gosterge(id),
  donem_yil     smallint not null,
  -- Periyoda göre okunur: 3 aylık 1-4 · 6 aylık 1-2 · yıllık 1.
  donem_no      smallint not null default 1,
  periyot       smallint not null default 6,
  pay           numeric(18,4) not null default 0,
  payda         numeric(18,4) not null default 0,
  -- Tetik yazar (fn_klinik_gosterge_sonuc); elle yazılan değer korunmaz.
  sonuc         numeric(18,4) not null default 0,
  -- Ölçüm anındaki hedef DONDURULUR: rehber hedefi sonradan değişirse geçmiş
  --   dönemin "hedefte miydi" yargısı değişmemeli.
  hedef_yon     varchar(2),
  hedef_deger   numeric(10,4),
  -- 0 taslak · 1 kesinleşti (Bakanlık sistemine girildi, artık hesaplanmaz)
  durum         smallint not null default 0,
  -- 0 otomatik hesaplandı · 1 elle girildi
  kaynak        smallint not null default 0,
  aciklama      text not null default '',
  ekleyen       integer not null default 0,
  ekleme_tarihi timestamptz not null default now(),
  degistiren    integer not null default 0,
  degistirme_tarihi timestamptz
);
create unique index if not exists ux_klinik_gosterge_donem
  on public.klinik_gosterge_donem (sube_id, gosterge_id, donem_yil, donem_no, periyot);
create index if not exists ix_klinik_gosterge_donem_yil
  on public.klinik_gosterge_donem (donem_yil, donem_no);

-- =================================================================== hesap ==
-- Payda 0 ise sonuç 0'dır, pay değil: bu göstergelerin hepsi ORAN (rehberde
--   hesaplama yöntemi her zaman pay/payda × 100). Payda yoksa o dönem hiç vaka
--   yok demektir; payı sonuç diye yazmak "3 hasta" yerine "%3" göstermek olurdu.
create or replace function public.fn_klinik_gosterge_sonuc(
    p_pay numeric, p_payda numeric
) returns numeric
language sql immutable
as $fn$
  select case when coalesce(p_payda, 0) = 0 then 0
              else round(coalesce(p_pay, 0) / p_payda * 100, 4) end;
$fn$;

create or replace function public.fn_klinik_gosterge_donem_hesapla()
returns trigger
language plpgsql
as $tg$
begin
    new.sonuc := public.fn_klinik_gosterge_sonuc(new.pay, new.payda);
    return new;
end;
$tg$;

drop trigger if exists tg_klinik_gosterge_donem_hesapla on public.klinik_gosterge_donem;
create trigger tg_klinik_gosterge_donem_hesapla
  before insert or update of pay, payda on public.klinik_gosterge_donem
  for each row execute function public.fn_klinik_gosterge_donem_hesapla();

-- ================================================================== lookup ==
-- Kart combosu göstergeyi KOD + AD ile gösterir: yalnız ad, "Hasta Düşme Oranı"
--   ile "FTR Hizmetlerinde Hasta Düşme Oranı"yı ayırır ama Bakanlık sistemine
--   giren kodu gizlerdi.
create or replace view public.v_klinik_gosterge_lookup as
select g.id, (g.kod || ' · ' || g.ad)::varchar(430) as ad, g.aktif
  from public.klinik_gosterge g
 where g.aktif = 1;


-- ============================================================ 16 olgu ==
insert into public.klinik_olgu (kod, ad, sira)
select v.kod, v.ad, v.sira from (values
  ('DP', 'Diz Protezi', 1),
  ('GD', 'Gebelik Süreci ve Doğum', 2),
  ('DM', 'Diabetes Mellitus', 3),
  ('KP', 'Kalça Protezi', 4),
  ('İN', 'İnme', 5),
  ('KK', 'Koroner Kalp Hastalığı', 6),
  ('KH', 'Kronik Obstrüktif Akciğer Hastalığı (KOAH)', 7),
  ('KA', 'Katarakt Cerrahisi', 8),
  ('KR', 'Kolorektal Kanser', 9),
  ('PR', 'Prostat Kanseri', 10),
  ('Dİ', 'Diş İmplantı', 11),
  ('ÇA', 'Çocukluk Çağı Astımları', 12),
  ('MK', 'Meme Kanseri', 13),
  ('BM', 'Bariatrik ve Metabolik Cerrahi', 14),
  ('HT', 'Hipertansiyon', 15),
  ('KB', 'Kronik Böbrek Yetmezliği', 16)
  ) as v(kod, ad, sira)
on conflict (kod) do update set ad = excluded.ad, sira = excluded.sira;

-- ======================================================= 217 gösterge ==
insert into public.klinik_gosterge (olgu_id, kod, ad, tanim, standart_metin, hesaplama,
       teknik_not, hedef_grup, haric, izlem, hedef_metin, hedef_yon, hedef_deger,
       hedef_birim, periyot_metin, periyot, otomatik)
select o.id, v.kod, v.ad, v.tanim, v.standart_metin, v.hesaplama,
       v.teknik_not, v.hedef_grup, v.haric, v.izlem, v.hedef_metin, v.hedef_yon,
       v.hedef_deger, v.hedef_birim, v.periyot_metin, v.periyot, v.otomatik
  from (values
  ('DP', 'DP.G1', 'Diz Protezi Operasyonu Geçiren Hastalarda Patella Dislokasyonu Nedeni ile Yeniden Yatış Oranı (İlk 2ay)', 'Diz protezi operasyonu geçiren hastalardan operasyon sonrası ilk 2 ay içerisinde "Patella Dislokasyonu" nedeni ile yeniden yatışı yapılan hastaların oranını ifade etmektedir.', 'Tüm hastaların etkin bir diz protez operasyonu geçirmesi sağlanmalıdır.', 'İlgili dönemde; (Diz protezi operasyonu geçiren hastalardan dislokasyon nedeni ile yeniden yatan tekil hasta sayısı/ Diz protezi operasyonu geçirmiş toplam tekil hasta sayısı) X 100', 'Pay: Paydadaki hastalar içinde dislokasyon ICD 10 tanı kodlarından herhangi birini ana veya ek tanı olarak alan ve SUT kodlarından herhangi birini alarak operasyon tarihinden itibaren ilk 60 gün içerisinde yeniden yatan tekil hasta sayısı Not: Payın hesaplanması için dislokasyon ICD 10 kodlarından herhangi biri ve/veya dislokasyon nedeniyle gerçekleştirilen işlemlerle ilişkili SUT kodlarından herhangi birini alarak yatışı yapılan hastalar hesaplamaya dâhil edilir. Örnek: 15 Mart tarihinde operasyon geçiren hastalar 14 Mayıs tarihine kadar izlenecektir. Payda: Ölçüm yapılan ilgili dönemde diz protezi operasyonu SUT kodunu alan toplam tekil hasta sayısı', '18 yaş ve üstündeki hastalar', '', 'UBK', '≤ %0.8', '<=', 0.8, 'yuzde', '6 aylık, yıllık', 6, 1),
  ('DP', 'DP.G2', 'Diz Protezi Operasyonu Yapılan Hastalarda Reoperasyon Geçiren Hasta Oranı (İlk 2 ay)', 'Diz protezi operasyonu geçiren hastalardan operasyon sonrası ilk 2 ay içerisinde aynı tarafa reoperasyon yapılan hasta oranını ifade etmektedir.', 'Tüm hastaların etkin bir diz protezi operasyonu geçirmesi sağlanmalıdır.', 'İlgili dönemde; (Paydada yer alan hastalarda diz protezi operasyonunu geçirdikten sonraki ilk 2 ay içerisinde aynı tarafa reoperasyon yapılan tekil hasta sayısı / Diz protezi operasyonu geçirmiş toplam tekil hasta sayısı) X', 'Pay: Paydadaki hastalar içinde diz protezi operasyonu sonrası aynı taraf için reoperasyon SUT kodlarından herhangi birini alan operasyon tarihinden itibaren ilk 60 gün içerisindeki tekil hasta sayısı Örnek: 15 Mart tarihinde operasyon geçiren hastalar 14 Mayıs tarihine kadar izlenecektir. Payda: Ölçüm yapılan ilgili dönemde diz protezi operasyonu SUT kodunu alan toplam tekil hasta sayısı Not: Hasta tekilleştirilirken opere edilen diz tarafı (sağ/sol/bilateral) dikkate alınır.', '18 yaş ve üstündeki hastalar', '', 'UBK', '≤ %5', '<=', 5, 'yuzde', '6 aylık, yıllık', 6, 1),
  ('DP', 'DP.G3', 'Diz Protezi Operasyonu Yapılan Hastalarda Reoperasyon Geçiren Hasta Oranı (İlk 12 ay)', 'Diz protezi operasyonunu geçirdikten sonra ilk 12 ay içerisinde aynı tarafa reoperasyon yapılan hasta oranını ifade etmektedir.', 'Tüm hastaların etkin bir diz protezi operasyonu geçirmesi sağlanmalıdır.', 'İlgili dönemde; (Paydada yer alan hastalarda diz protezi operasyonunu geçirdikten sonra 12 ay içerisinde aynı tarafa reoperasyon yapılan tekil hasta sayısı / Diz protezi operasyonu geçirmiş toplam tekil hasta sayısı) X', 'Pay: Paydada yer alan hastalarda diz protezi operasyonunu geçirdikten sonra 12 ay içerisinde aynı taraf için reoperasyon SUT kodlarından herhangi birini alan tekil hasta sayısı Örnek: 15 Ocak tarihinde operasyon geçiren hastalar bir sonraki yıl 15 Ocak tarihine kadar izlenecektir. Payda: Ölçüm yapılan ilgili dönemde diz protezi operasyonu SUT kodunu alan toplam tekil hasta sayısı Not: Hasta tekilleştirilirken opere edilen diz tarafı (sağ/sol/biletaral) dikkate alınır.', '18 yaş ve üstündeki hastalar', '', 'UBK', '≤ %5', '<=', 5, 'yuzde', '6 aylık, yıllık', 6, 1),
  ('DP', 'DP.G4', 'Diz Protezi Operasyonu Geçiren Hastalarda Hastanede Ortalama Yatış Gün Sayısı', 'Diz protezi operasyonunu geçiren hastaların operasyon tarihinden itibaren hastanede ortalama yatış gün sayısını ifade etmektedir.', 'Tüm hastaların etkin bir diz protezi operasyonu geçirmesi sağlanmalıdır.', 'İlgili dönemde; (Paydada yer alan hastaların operasyon tarihinden itibaren hastanede yatış gün sayıları toplamı /Diz protezi operasyonu sayısı)', 'Pay: Paydada yer alan hastaların operasyon tarihinden itibaren yatış gün sayıları toplamıdır. İlgili dönemde yatan tüm hastaların yatış gün süreleri diğer aylara sarksa bile hesaplamaya dahil edilmelidir. Payda: Ölçüm yapılan ilgili dönemde diz protezi SUT kodu ile gerçekleştirilen operasyon sayısı (Hastanın aynı dönemde aynı operasyon kodu (sağ/sol/bilateral) ile birden fazla yatışı varsa her bir yatış pay ve paydaya dahil edilir)', '18 yaş ve üstündeki hastalar', '', 'UBK', '≤ 3 gün', '<=', 3, 'gün', '6 aylık, yıllık', 6, 1),
  ('DP', 'DP.G5', 'Diz Protezi Operasyonu Geçiren Hastalarda Perioperatif Dönemde Profilaktik Antibiyotik Verilen Hasta Oranı', 'Diz protezi operasyonu geçiren hastalarda perioperatif dönemde uygun şekilde profilaktik antibiyotik verilen hasta oranını ifade etmektedir.', 'Diz protezi operasyonu ile ilgili enfeksiyonların önlenmesi için gerekli tedbirler alınmalıdır.', 'İlgili dönemde; (Paydadaki hastalar içinde yatışı süresince en fazla dört doz antibiyotik order edilen hasta sayısı / Diz protezi operasyonu sayısı) X 100', 'Pay: Paydada yer alan hastalarda, yatış süresince veri kaynağında ATC ilaç kodlarından herhangi birini alıp en fazla dört doz antibiyotik order edilen hasta sayısı Payda: Ölçüm yapılan ilgili dönemde diz protezi SUT kodu ile gerçekleştirilen operasyon sayısı (Hastanın aynı dönemde aynı operasyon kodu (sağ/sol/bilateral) ile birden fazla yatışı varsa her bir yatış pay ve paydaya dahil edilir)', '18 yaş ve üstündeki hastalar', 'Dört doz üstünde antibiyotik verilen hastalar paya dahil edilmeyecektir.', 'UBK', '≥ %95', '>=', 95, 'yuzde', '6 aylık, yıllık', 6, 1),
  ('DP', 'DP.G6', 'Diz Protezi Operasyonu Geçiren Hastalarda Cerrahi Alan Enfeksiyonu Tespit Edilen Hasta Oranı (İlk 2 ay)', 'Diz protezi operasyonu geçirdikten sonraki 2 ay içinde cerrahi alan enfeksiyonu tespit edilen hasta oranını ifade etmektedir.', 'Diz protezi operasyonu ile ilgili enfeksiyonların önlenmesi için gerekli tedbirler alınmalıdır.', 'İlgili dönemde; (Paydada yer alan hastalarda, operasyondan sonraki 2 ay içinde cerrahi alan enfeksiyonu tespit edilen tekil hasta sayısı / Diz protezi operasyonu geçirmiş toplam tekil hasta sayısı) X 100', 'Pay: Paydada yer alan hastalarda operasyondan sonraki 60 gün içinde aynı taraf için (sağ/sol/bilateral) cerrahi alan enfeksiyonu ICD 10 tanı kodlarından herhangi birini ana veya ek tanı olarak ya da SUT kodlarından herhangi birini alan tekil hasta sayısı Örnek: 15 Mart tarihinde operasyon geçiren hastalar 14 Mayıs tarihine kadar izlenecektir. Payda: Ölçüm yapılan ilgili dönemde diz protezi operasyonu SUT kodunu alan toplam tekil hasta sayısı', '18 yaş ve üstündeki hastalar', '', 'UBK', '≤ %5', '<=', 5, 'yuzde', '6 aylık, yıllık', 6, 1),
  ('DP', 'DP.G7', 'Diz Protezi Operasyonu Geçiren Hastalarda Cerrahi Alan Enfeksiyonu Tespit Edilen Hasta Oranı(2 ay-12 ay)', 'Diz protezi operasyonu geçirdikten sonraki 2-12 ay içinde cerrahi alan enfeksiyonu tespit edilen hasta oranını ifade etmektedir.', 'Diz protezi operasyonu ile ilgili enfeksiyonların önlenmesi için gerekli tedbirler alınmalıdır.', 'İlgili dönemde; (Paydada yer alan hastalarda, operasyondan sonraki 2-12 ay içinde cerrahi alan enfeksiyonu tespit edilen hasta sayısı / Diz protezi operasyonu sayısı) X', 'Pay: Paydada yer alan hastalarda operasyondan sonraki 60 gün ile 12 ay içinde aynı taraf için (sağ/sol/bilateral) cerrahi alan enfeksiyonu ICD 10 tanı kodlarından herhangi birini ana veya ek tanı olarak ya da SUT kodlarından herhangi birini alan hasta sayısı Örnek: 15 Mart tarihinde operasyon geçiren hastalar, 14 Mayıs tarihi ile bir sonraki yıl 15 Mart tarihleri arasında izlenecektir. Payda: Ölçüm yapılan ilgili dönemde diz protezi SUT kodu ile gerçekleştirilen operasyon sayısı', '18 yaş ve üstündeki hastalar', '', 'UBK', '≤ %5', '<=', 5, 'yuzde', '6 aylık, yıllık', 6, 1),
