-- =============================================================== yetki ==
-- Ekran yetkisi KAYNAK (tur 0); tur 1 ekran açmaz (692 dersi).
insert into public.yetki (kod, ad, grup, tur, sira, aktif)
select 'klinik_kalite', 'Klinik Kalite', 'Kalite', 0, 41, 1
 where not exists (select 1 from public.yetki where kod = 'klinik_kalite');

insert into public.yetki (kod, ad, grup, tur, sira, aktif)
select v.kod, v.ad, 'Kalite', v.tur, v.sira, 1 from (values
    ('klinik_kalite.olgu',        'Sağlık olguları ve göstergeler', 0, 1),
    ('klinik_kalite.donem',       'Dönem sonuçları',                0, 2),
    ('klinik_kalite.hesapla',     'Dönemi hesapla',                 1, 3),
    ('klinik_kalite.kesinlestir', 'Dönemi kesinleştir',             1, 4),
    ('klinik_kalite.hedef',       'Kurum hedefi belirle',           1, 5)
  ) as v(kod, ad, tur, sira)
 where not exists (select 1 from public.yetki y where y.kod = v.kod);

insert into public.rol_yetki (rol_id, yetki_id, gor, ekle, degistir, sil, ekleyen)
select r.id, y.id, 1, 1, 1, 1, 0
  from public.rol r cross join public.yetki y
 where r.kod = 'yonetici'
   and (y.kod = 'klinik_kalite' or y.kod like 'klinik_kalite.%')
   and not exists (select 1 from public.rol_yetki ry
                    where ry.rol_id = r.id and ry.yetki_id = y.id);

